import{Ionicons}from'@expo/vector-icons';import{LinearGradient}from'expo-linear-gradient';import{router}from'expo-router';import{ScrollView,StyleSheet,Text,Pressable,TextInput,View}from'react-native';import{SafeAreaView}from'react-native-safe-area-context';import{C}from'../constants/theme';const effects=[['Cinematic','🎞️'],['Blur','🌫️'],['VHS','📼'],['Glitch','⚡'],['Film','🎥'],['Light Leak','☀️'],['Retro','📻'],['B&W','⚫'],['Dream','🌙'],['Neon','💜'],['Zoom','💨'],['Shake','📳']];export default function Effects(){return <SafeAreaView style={s.safe}><View style={s.head}><Pressable onPress={()=>router.back()}><Ionicons name="chevron-forward" size={25} color={C.text}/></Pressable><Text style={s.title}>التأثيرات</Text></View><View style={s.search}><Ionicons name="search" size={18} color={C.muted}/><TextInput placeholder="إبحث عن تأثير..." placeholderTextColor={C.muted} style={s.input}/></View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.filters}>{['الكل','سينمائي','ضوء','ألوان','مميز'].map((x,i)=><View key={x} style={[s.filter,i===0&&s.active]}><Text style={s.ft}>{x}</Text></View>)}</ScrollView><ScrollView contentContainerStyle={s.grid}>{effects.map((e,i)=><Pressable key={e[0]} style={s.card} onPress={()=>router.push('/editor')}><LinearGradient colors={i%2?['#26303D','#141A22']:['#37205B','#171C29']} style={s.art}><Text style={s.emoji}>{e[1]}</Text></LinearGradient><Text style={s.n}>{e[0]}</Text></Pressable>)}</ScrollView></SafeAreaView>}const s=StyleSheet.create({safe:{flex:1,backgroundColor:C.bg},head:{height:58,paddingHorizontal:16,flexDirection:'row-reverse',alignItems:'center',justifyContent:'space-between'},title:{color:C.text,fontSize:18,fontWeight:'900'},search:{height:44,margin:8,borderRadius:13,backgroundColor:C.surface,borderWidth:1,borderColor:C.border,flexDirection:'row-reverse',alignItems:'center',paddingHorizontal:12,gap:8},input:{flex:1,color:C.text,textAlign:'right'},filters:{paddingHorizontal:10,gap:7,marginBottom:12},filter:{paddingHorizontal:18,height:34,borderRadius:10,backgroundColor:C.surface,alignItems:'center',justifyContent:'center'},active:{backgroundColor:C.purple},ft:{color:C.text,fontSize:11,fontWeight:'800'},grid:{padding:10,flexDirection:'row-reverse',flexWrap:'wrap',gap:10},card:{width:'31%',gap:6},art:{height:110,borderRadius:14,alignItems:'center',justifyContent:'center',borderWidth:1,borderColor:C.border},emoji:{fontSize:38},n:{color:C.text,fontSize:10,textAlign:'right',fontWeight:'800'}});